function GlassKilnDoorLifterMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassKilnDoorLifterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassKilnDoorLifterMaker.ironStock=GlassKilnDoorLifterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassKilnDoorLifterMaker.bronzeStock=GlassKilnDoorLifterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassKilnDoorLifterMaker.woodStock=GlassKilnDoorLifterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassKilnDoorLifterMaker.leatherStock=GlassKilnDoorLifterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassKilnDoorLifterMaker.silverStock=GlassKilnDoorLifterMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassKilnDoorLifterMaker.goldStock=GlassKilnDoorLifterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassKilnDoorLifterMaker.jewelStock=GlassKilnDoorLifterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassKilnDoorLifterMaker.pearlStock=GlassKilnDoorLifterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassKilnDoorLifterMaker.maker then t=math.max(1,t-math.floor(GlassKilnDoorLifterMaker.maker.skill/13)) end; table.insert(GlassKilnDoorLifterMaker.activeMaking,{id="glasskilndoorlifter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassKilnDoorLifterMaker.completeMaking(m) local q=1.0+(GlassKilnDoorLifterMaker.getQualityBonus()/100); if GlassKilnDoorLifterMaker.maker then q=q+(GlassKilnDoorLifterMaker.maker.skill/140) end; q=math.min(2.5,q); GlassKilnDoorLifterMaker.productStock[m.productType]=(GlassKilnDoorLifterMaker.productStock[m.productType] or 0)+m.quantity; GlassKilnDoorLifterMaker.totalProducts=GlassKilnDoorLifterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassKilnDoorLifterMaker.maker then GlassKilnDoorLifterMaker.maker.itemsMade=GlassKilnDoorLifterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassKilnDoorLifterMaker.maker.skill=math.min(100,GlassKilnDoorLifterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dvigovalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasskilndoorlifter.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassKilnDoorLifterMaker.update(dt) if not _G.state then return end; GlassKilnDoorLifterMaker.dayTimer=GlassKilnDoorLifterMaker.dayTimer+dt; if GlassKilnDoorLifterMaker.dayTimer>=30 then GlassKilnDoorLifterMaker.dayTimer=0; for i=#GlassKilnDoorLifterMaker.activeMaking,1,-1 do local m=GlassKilnDoorLifterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassKilnDoorLifterMaker.completeMaking(m); table.remove(GlassKilnDoorLifterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassKilnDoorLifterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassKilnDoorLifterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
